#pragma once

/* PORT_HOOKABLE(name): a game function mods can hook (docs/MODDING.md,
 * "Code mods"). On the GameCube and in builds without mods, the name as it
 * is. With mods (PORT_MODS), the definition becomes name__body, and a
 * dispatcher named name, generated by tools/port/gen_hooks.py and included at
 * the end of the file, calls the mods' hooks around it. */
#ifdef PORT_MODS
#define PORT_HOOKABLE(name) name##__body
#else
#define PORT_HOOKABLE(name) name
#endif
